import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { createStore } from "./lib/store.js";
import { bookPage, homePage, notFoundPage } from "./lib/views.js";

const PORT = process.env.PORT || 3000;
const store = createStore(new URL("./data/books.json", import.meta.url).pathname);

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => {
      body += chunk;
      if (body.length > 1_000_000) req.destroy();
    });
    req.on("end", () => resolve(new URLSearchParams(body)));
    req.on("error", reject);
  });
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function html(res, body, status = 200) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(body);
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const path = url.pathname;

  try {
    if (req.method === "GET" && path === "/") {
      return html(res, homePage(store.all()));
    }

    if (req.method === "POST" && path === "/books") {
      const form = await parseBody(req);
      const title = form.get("title") || "";
      const author = form.get("author") || "";
      if (!title.trim() || !author.trim()) {
        return html(res, homePage(store.all(), "Title and author are required."), 400);
      }
      const book = store.add({ title, author, notes: form.get("notes") });
      return redirect(res, `/books/${book.id}`);
    }

    const bookMatch = path.match(/^\/books\/([0-9a-f-]{36})(\/finish|\/notes)?$/);
    if (bookMatch) {
      const [, id, action] = bookMatch;
      const book = store.get(id);
      if (!book) return html(res, notFoundPage(), 404);

      if (req.method === "GET" && !action) {
        return html(res, bookPage(book));
      }
      if (req.method === "POST" && action === "/finish") {
        store.finish(id);
        return redirect(res, `/books/${id}`);
      }
      if (req.method === "POST" && action === "/notes") {
        const form = await parseBody(req);
        store.updateNotes(id, form.get("notes") || "");
        return redirect(res, `/books/${id}`);
      }
    }

    if (req.method === "GET" && path === "/style.css") {
      const css = await readFile(new URL("./public/style.css", import.meta.url));
      res.writeHead(200, { "Content-Type": "text/css" });
      return res.end(css);
    }

    html(res, notFoundPage(), 404);
  } catch (err) {
    console.error(err);
    res.writeHead(500, { "Content-Type": "text/plain" });
    res.end("Internal Server Error");
  }
});

server.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
});

