function esc(s) {
  return String(s ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function layout(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${esc(title)} · Book Tracker</title>
  <link rel="stylesheet" href="/style.css">
</head>
<body>
  <main>
    <header><a href="/" class="brand">📖 Book Tracker</a></header>
    ${content}
  </main>
</body>
</html>`;
}

function bookItem(book) {
  const finished = book.status === "finished";
  return `<li>
    <a href="/books/${book.id}"><strong>${esc(book.title)}</strong></a>
    <span class="author">by ${esc(book.author)}</span>
    ${finished ? `<span class="date">finished ${esc(book.finishedAt.slice(0, 10))}</span>` : `
    <form method="post" action="/books/${book.id}/finish" class="inline">
      <button type="submit">Mark finished</button>
    </form>`}
  </li>`;
}

function bookList(title, books, empty) {
  return `<section>
    <h2>${esc(title)}</h2>
    ${books.length ? `<ul class="books">${books.map(bookItem).join("")}</ul>` : `<p class="empty">${esc(empty)}</p>`}
  </section>`;
}

export function homePage(books, error = null) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");
  return layout("Home", `
    ${error ? `<p class="error">${esc(error)}</p>` : ""}
    ${bookList("Currently reading", reading, "Nothing on the go. Add a book below!")}
    ${bookList("Finished", finished, "No finished books yet.")}
    <section>
      <h2>Add a book</h2>
      <form method="post" action="/books" class="card">
        <label>Title <input name="title" required></label>
        <label>Author <input name="author" required></label>
        <label>Notes <textarea name="notes" rows="3"></textarea></label>
        <button type="submit">Add book</button>
      </form>
    </section>`);
}

export function bookPage(book) {
  const finished = book.status === "finished";
  return layout(book.title, `
    <article class="card">
      <h1>${esc(book.title)}</h1>
      <p class="author">by ${esc(book.author)}</p>
      <p class="meta">
        Status: ${finished ? `Finished ${esc(book.finishedAt.slice(0, 10))}` : "Currently reading"}
      </p>
      ${finished ? "" : `
      <form method="post" action="/books/${book.id}/finish">
        <button type="submit">Mark finished</button>
      </form>`}
    </article>
    <section>
      <h2>My notes</h2>
      ${book.notes ? `<p class="notes">${esc(book.notes).replaceAll("\n", "<br>")}</p>` : `<p class="empty">No notes yet.</p>`}
      <form method="post" action="/books/${book.id}/notes" class="card">
        <label>Edit notes <textarea name="notes" rows="5">${esc(book.notes)}</textarea></label>
        <button type="submit">Save notes</button>
      </form>
    </section>
    <p><a href="/">← Back to all books</a></p>`);
}

export function notFoundPage() {
  return layout("Not found", `
    <h1>404</h1>
    <p>That page doesn't exist.</p>
    <p><a href="/">← Back to all books</a></p>`);
}

